    "path": "Blasphemous2Trainer/Program.cs",
    "content": "using System;\nusing System.Threading;\nusing Blasphemous2Trainer.Memory;\n\nnamespace Blasphemous2Trainer\n{\n    /// <summary>\n    /// Entry point for the Blasphemous 2 Trainer application.\n    /// Provides a console-based interface for toggling game cheats.\n    /// </summary>\n    internal class Program\n    {\n        private static GameManager? _gameManager;\n\n        static void Main(string[] args)\n        {\n            Console.WriteLine(\"Blasphemous 2 Trainer v1.0\");\n            Console.WriteLine(\"Attempting to attach to Blasphemous 2 process...\");\n\n            try\n            {\n                _gameManager = new GameManager();\n                Console.WriteLine(\"Successfully attached to Blasphemous 2.\");\n            }\n            catch (Exception ex)\n            {\n                Console.WriteLine($\"Failed to attach: {ex.Message}\");\n                Console.WriteLine(\"Make sure the game is running.\");\n                Console.WriteLine(\"Press any key to exit.\");\n                Console.ReadKey();\n                return;\n            }\n\n            Console.WriteLine(\"\\nHotkeys:\");\n            Console.WriteLine(\"  F1 - Toggle Infinite Health\");\n            Console.WriteLine(\"  F2 - Toggle Infinite Fervour\");\n            Console.WriteLine(\"  F3 - Add 1000 Tears of Atonement\");\n            Console.WriteLine(\"  Escape - Exit trainer\");\n            Console.WriteLine(\"\\nStatus:\");\n\n            bool running = true;\n            while (running)\n            {\n                if (Console.KeyAvailable)\n                {\n                    var key = Console.ReadKey(true).Key;\n                    switch (key)\n                    {\n                        case ConsoleKey.F1:\n                            _gameManager.ToggleInfiniteHealth();\n                            Console.WriteLine($\"  Infinite Health: {(_gameManager.InfiniteHealthEnabled ? \"ON\" : \"OFF\")}\");\n                            break;\n                        case ConsoleKey.F2:\n                            _gameManager.ToggleInfiniteFervour();\n                            Console.WriteLine($\"  Infinite Fervour: {(_gameManager.InfiniteFervourEnabled ? \"ON\" : \"OFF\")}\");\n                            break;\n                        case ConsoleKey.F3:\n                            _gameManager.AddTears(1000);\n                            Console.WriteLine(\"  1000 Tears of Atonement added.\");\n                            break;\n                        case ConsoleKey.Escape:\n                            running = false;\n                            break;\n                    }\n                }\n                _gameManager.ApplyCheats(); // Continuously apply cheats while active\n                Thread.Sleep(50); // Prevent CPU hogging\n            }\n\n            _gameManager.Cleanup();\n            Console.WriteLine(\"Trainer detached. Goodbye!\");\n        }\n    }\n}\n"
  },
