    "path": "Blasphemous2Trainer/Memory/GameManager.cs",
    "content": "using System;\nusing System.Diagnostics;\nusing MemorySharp;\n\nnamespace Blasphemous2Trainer.Memory\n{\n    /// <summary>\n    /// Manages memory interactions with the Blasphemous 2 game process.\n    /// Provides methods to read/write game state for cheats.\n    /// </summary>\n    public class GameManager : IDisposable\n    {\n        private readonly MemorySharp.MemorySharp _memory;\n        private readonly Process _gameProcess;\n        private readonly IntPtr _healthAddress;\n        private readonly IntPtr _fervourAddress;\n        private readonly IntPtr _tearsAddress;\n\n        /// <summary>\n        /// Gets a value indicating whether infinite health is currently enabled.\n        /// </summary>\n        public bool InfiniteHealthEnabled { get; private set; }\n\n        /// <summary>\n        /// Gets a value indicating whether infinite fervour is currently enabled.\n        /// </summary>\n        public bool InfiniteFervourEnabled { get; private set; }\n\n        /// <summary>\n        /// Initializes a new instance of the <see cref=\"GameManager\"/> class.\n        /// Attaches to the Blasphemous 2 process and resolves memory addresses.\n        /// </summary>\n        /// <exception cref=\"InvalidOperationException\">Thrown if the game process is not found or addresses cannot be resolved.</exception>\n        public GameManager()\n        {\n            // Find the Blasphemous 2 process\n            var processes = Process.GetProcessesByName(\"Blasphemous 2\");\n            if (processes.Length == 0)\n            {\n                processes = Process.GetProcessesByName(\"Blasphemous2\");\n            }\n            if (processes.Length == 0)\n            {\n                throw new InvalidOperationException(\"Blasphemous 2 process not found.\");\n            }\n\n            _gameProcess = processes[0];\n            _memory = new MemorySharp.MemorySharp(_gameProcess);\n\n            // Resolve pointer chains for game variables (example offsets, would need reverse engineering)\n            // Base address is typically the game module + static offset\n            IntPtr moduleBase = _gameProcess.MainModule.BaseAddress;\n\n            // Health pointer chain: base + 0x01234567 -> +0x10 -> +0x20 -> +0x30\n            _healthAddress = ResolvePointer(moduleBase + 0x01234567, new int[] { 0x10, 0x20, 0x30 });\n            // Fervour pointer chain: base + 0x02345678 -> +0x08 -> +0x18\n            _fervourAddress = ResolvePointer(moduleBase + 0x02345678, new int[] { 0x08, 0x18 });\n            // Tears pointer chain: base + 0x03456789 -> +0x0C\n            _tearsAddress = ResolvePointer(moduleBase + 0x03456789, new int[] { 0x0C });\n\n            InfiniteHealthEnabled = false;\n            InfiniteFervourEnabled = false;\n        }\n\n        /// <summary>\n        /// Resolves a pointer chain from a given base address using offsets.\n        /// </summary>\n        /// <param name=\"baseAddress\">The starting memory address.</param>\n        /// <param name=\"offsets\">The offsets to dereference sequentially.</param>\n        /// <returns>The final resolved address.</returns>\n        private IntPtr ResolvePointer(IntPtr baseAddress, int[] offsets)\n        {\n            IntPtr current = baseAddress;\n            foreach (int offset in offsets)\n            {\n                // Read the pointer at current address\n                IntPtr next = _memory.Read<IntPtr>(current);\n                current = next + offset;\n            }\n            return current;\n        }\n\n        /// <summary>\n        /// Toggles infinite health on or off.\n        /// </summary>\n        public void ToggleInfiniteHealth()\n        {\n            InfiniteHealthEnabled = !InfiniteHealthEnabled;\n            if (InfiniteHealthEnabled)\n            {\n                // Set health to a high value (e.g., 9999)\n                _memory.Write(_healthAddress, 9999.0f);\n            }\n        }\n\n        /// <summary>\n        /// Toggles infinite fervour on or off.\n        /// </summary>\n        public void ToggleInfiniteFervour()\n        {\n            InfiniteFervourEnabled = !InfiniteFervourEnabled;\n            if (InfiniteFervourEnabled)\n            {\n                // Set fervour to a high value (e.g., 999)\n                _memory.Write(_fervourAddress, 999.0f);\n            }\n        }\n\n        /// <summary>\n        /// Adds a specified amount of Tears of Atonement to the player's currency.\n        /// </summary>\n        /// <param name=\"amount\">The amount of tears to add.</param>\n        public void AddTears(int amount)\n        {\n            int currentTears = _memory.Read<int>(_tearsAddress);\n            currentTears += amount;\n            _memory.Write(_tearsAddress, currentTears);\n        }\n\n        /// <summary>\n        /// Applies active cheats each frame. Called periodically to maintain cheat states.\n        /// </summary>\n        public void ApplyCheats()\n        {\n            if (InfiniteHealthEnabled)\n            {\n                _memory.Write(_healthAddress, 9999.0f);\n            }\n            if (InfiniteFervourEnabled)\n            {\n                _memory.Write(_fervourAddress, 999.0f);\n            }\n        }\n\n        /// <summary>\n        /// Cleans up resources and detaches from the game process.\n        /// </summary>\n        public void Cleanup()\n        {\n            // Optionally reset values to normal\n            if (InfiniteHealthEnabled)\n            {\n                _memory.Write(_healthAddress, 100.0f); // Default health\n            }\n            if (InfiniteFervourEnabled)\n            {\n                _memory.Write(_fervourAddress, 50.0f); // Default fervour\n            }\n        }\n\n        /// <summary>\n        /// Disposes the memory sharp instance and releases resources.\n        /// </summary>\n        public void Dispose()\n        {\n            _memory?.Dispose();\n            _gameProcess?.Dispose();\n            GC.SuppressFinalize(this);\n        }\n    }\n}\n"
  },
