    "path": "Blasphemous2Trainer/Config/TrainerConfig.cs",
    "content": "using System.IO;\nusing Newtonsoft.Json;\n\nnamespace Blasphemous2Trainer.Config\n{\n    /// <summary>\n    /// Configuration settings for the Blasphemous 2 Trainer.\n    /// Allows customization of memory addresses and hotkeys without recompilation.\n    /// </summary>\n    public class TrainerConfig\n    {\n        /// <summary>\n        /// Gets or sets the base address offset for health (relative to module base).\n        /// </summary>\n        [JsonProperty(\"health_base_offset\")]\n        public string HealthBaseOffset { get; set; } = \"0x01234567\";\n\n        /// <summary>\n        /// Gets or sets the pointer offsets for health.\n        /// </summary>\n        [JsonProperty(\"health_offsets\")]\n        public int[] HealthOffsets { get; set; } = { 0x10, 0x20, 0x30 };\n\n        /// <summary>\n        /// Gets or sets the base address offset for fervour.\n        /// </summary>\n        [JsonProperty(\"fervour_base_offset\")]\n        public string FervourBaseOffset { get; set; } = \"0x02345678\";\n\n        /// <summary>\n        /// Gets or sets the pointer offsets for fervour.\n        /// </summary>\n        [JsonProperty(\"fervour_offsets\")]\n        public int[] FervourOffsets { get; set; } = { 0x08, 0x18 };\n\n        /// <summary>\n        /// Gets or sets the base address offset for Tears of Atonement.\n        /// </summary>\n        [JsonProperty(\"tears_base_offset\")]\n        public string TearsBaseOffset { get; set; } = \"0x03456789\";\n\n        /// <summary>\n        /// Gets or sets the pointer offsets for Tears.\n        /// </summary>\n        [JsonProperty(\"tears_offsets\")]\n        public int[] TearsOffsets { get; set; } = { 0x0C };\n\n        /// <summary>\n        /// Loads configuration from a JSON file.\n        /// </summary>\n        /// <param name=\"filePath\">Path to the config file.</param>\n        /// <returns>A populated <see cref=\"TrainerConfig\"/> instance.</returns>\n        public static TrainerConfig LoadFromFile(string filePath)\n        {\n            if (!File.Exists(filePath))\n            {\n                return new TrainerConfig(); // Return default if not found\n            }\n\n            string json = File.ReadAllText(filePath);\n            return JsonConvert.DeserializeObject<TrainerConfig>(json) ?? new TrainerConfig();\n        }\n\n        /// <summary>\n        /// Saves the current configuration to a JSON file.\n        /// </summary>\n        /// <param name=\"filePath\">Path to save the config file.</param>\n        public void SaveToFile(string filePath)\n        {\n            string json = JsonConvert.SerializeObject(this, Formatting.Indented);\n            File.WriteAllText(filePath, json);\n        }\n    }\n}\n"
  },
